<?php
declare(strict_types=1);
$probe=json_decode((string)file_get_contents(__DIR__.'/runtime/probe.json'),true);$error='';$done=false;
if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim((string)$_POST['username']);$p=(string)$_POST['password'];if($u===''||strlen($p)<12)$error='Benutzername und Passwort mit mindestens 12 Zeichen erforderlich.';else{$r=['token'=>$probe['token'],'username'=>$u,'hash'=>password_hash($p,PASSWORD_ARGON2ID)];file_put_contents(__DIR__.'/runtime/request.json',json_encode($r),LOCK_EX);$done=true;}}
function h(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WAMS Setup</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#080c11;color:#e7edf4;font:13px system-ui}.box{width:370px;max-width:calc(100% - 28px);background:#111923;border:1px solid #293747;border-radius:5px;padding:24px}h1{text-align:center;margin:0 0 20px}label{display:block;margin:11px 0 5px;font-weight:650}input{width:100%;background:#0c1219;color:#e7edf4;border:1px solid #293747;border-radius:4px;padding:9px}button{width:100%;margin-top:16px;padding:9px;background:#56a5ff;border:0;border-radius:4px;font-weight:700}.error{border-left:3px solid #ff6677;padding:10px;background:#2a1419}</style></head><body><main class="box"><h1>WAMS</h1><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($done):?><p>Einrichtung wird abgeschlossen.</p><script>setTimeout(()=>location.replace('https://'+location.hostname+':<?=$probe['appPort']?>/login'),5000)</script><?php else:?><form method="post"><label>Benutzername</label><input name="username" required autofocus><label>Passwort</label><input type="password" name="password" minlength="12" required><button>Einrichten</button></form><?php endif?></main></body></html>
